#include "linux_web_file_manager.hpp"
#include <iostream>
#include <sodium.h>
namespace app=sfx::application;namespace web=sfx::apps::runtime::web;using Json=nlohmann::json;
namespace {unsigned checks{};void check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}struct Clock:app::IClock{std::uint64_t now{1000};std::uint64_t monotonic_millis()const noexcept override{return now;}std::int64_t unix_seconds()const noexcept override{return 1700000000;}};template<class F>void rejects(F f,const char* why){try{f();}catch(...){check(true,why);return;}check(false,why);}}
int main(){try{
    check(sodium_init()>=0,"crypto ready");app::Identifier128 job,op;job.bytes[0]=1;op.bytes[0]=2;
    Json rename={{"action","rename"},{"file","9007199254740993"},{"revision","4"},{"destination","1"},{"destination_revision","2"},{"filename","new.zip"}};const auto task=web::web_file_task(rename,job,op);
    check(task.operation.file.value==9007199254740993LL&&task.operation.expected_revision==4&&task.operation.operation==op,"exact identity and revision");
    auto invalid=rename;invalid["file"]=9007199254740993ULL;rejects([&]{web::web_file_task(invalid,job,op);},"numeric ids refused");invalid=rename;invalid["file"]="01";rejects([&]{web::web_file_task(invalid,job,op);},"noncanonical ids refused");invalid=rename;invalid["filename"]="../other";rejects([&]{web::web_file_task(invalid,job,op);},"path rename refused");invalid=rename;invalid["authority"]=true;rejects([&]{web::web_file_task(invalid,job,op);},"extra fields refused");
    Json query={{"kind","records"},{"area","0"},{"search","*.zip"},{"after","0"},{"selection","0"},{"pending_after",nullptr}};check(web::web_file_query(query).filter.search=="*.zip","filename search");check(web::web_file_query(query).filter.state==app::FileCatalogState::available,"normal lists exclude removed and missing history");query["kind"]="sql";rejects([&]{web::web_file_query(query);},"unknown query refused");
    Clock clock;unsigned starts{},reads{},cancels{};bool fail{};app::FileManagementTask original;app::FileManagementJobStatus current;current.job=job;current.code=app::LocalAccountResultCode::ok;current.state=app::FileManagementJobState::running;
    web::WebFileActions actions(clock,[&](const auto& t){++starts;if(starts==1)original=t;else check(app::encode_file_management_task(t)==app::encode_file_management_task(original),"retry preserves exact task");if(fail)throw std::runtime_error("lost reply");return current;},[&](auto id){++reads;check(id==job,"status same job");return current;},[&](auto id){++cancels;check(id==job,"cancel same job");current.cancellation_requested=true;return current;});
    auto review=actions.prepare("owner",task,rename);check(review&&!review->submitted&&starts==0,"prepare does not mutate");check(!actions.current("other")&&!actions.act("other",review->handle,"submit"),"cross browser refused");
    actions.act("owner",review->handle,"discard");check(!actions.current("owner")&&starts==0,"discard no mutation");review=actions.prepare("owner",task,rename);fail=true;auto result=actions.act("owner",review->handle,"submit");check(result->submitted&&!result->known&&starts==1,"uncertain start retained");
    check(!actions.prepare("owner",task,rename),"running blocks replacement");clock.now+=600001;check(actions.current("owner").has_value(),"active receipt does not expire");
    fail=false;result=actions.act("owner",review->handle,"retry");check(result->known&&starts==2,"explicit retry same request");actions.act("owner",review->handle,"submit");check(starts==2&&reads>0,"submit replay only checks");result=actions.act("owner",review->handle,"cancel");check(cancels==1&&result->status.cancellation_requested,"cancel is request not completion");
    current.state=app::FileManagementJobState::completed;check(actions.current("owner")->status.state==current.state,"actual completion observed");actions.act("owner",review->handle,"retry");check(starts==2,"completed task never reexecutes");
    auto viewtask=web::web_file_task({{"action","page"},{"target","01000000000000000000000000000000"},{"page","0"}},job,op);check(!actions.prepare("other",viewtask,{}),"foreign view cursor refused");
    app::FileManagementReadSnapshot snapshot;snapshot.code=app::LocalAccountResultCode::ok;app::ManagedFile file;file.file.id={9007199254740993LL};file.file.bytes=UINT64_MAX;file.file.name="<script>.zip";file.payload.volume="private-path";file.native_basename="private-placement";snapshot.records.push_back(file);const auto page=web::web_file_snapshot(snapshot);
    check(page["records"][0]["bytes"]=="18446744073709551615"&&page["records"][0]["id"]=="9007199254740993","lossless metadata");check(page.dump().find("private-")==std::string::npos,"native custody not exposed");
    app::FileManagementViewPage v;v.cursor=job;v.cells.push_back({27,7});current.view=v;const auto status=web::web_file_status(current);check(status["view"]["cells"][0][0]==27,"preview is inert cell data");
    actions.clear();check(!actions.current("owner"),"restore clears reviews");
    bool abandoned_done=false;web::WebFileActions abandoned(clock,[&](const auto& t){auto s=current;s.job=t.job;s.state=app::FileManagementJobState::running;return s;},[&](auto id){auto s=current;s.job=id;s.state=abandoned_done?app::FileManagementJobState::completed:app::FileManagementJobState::running;return s;},[&](auto){return current;});
    for(unsigned i=0;i<32;++i){auto t=task;t.job.bytes[1]=static_cast<std::uint8_t>(i);auto r=abandoned.prepare("owner"+std::to_string(i),t,rename);check(r.has_value(),"owner slot allocated");abandoned.act("owner"+std::to_string(i),r->handle,"submit");}
    clock.now+=600001;check(!abandoned.prepare("new",task,rename),"genuinely running abandoned jobs retained at cap");abandoned_done=true;check(abandoned.prepare("new",task,rename).has_value(),"expired abandoned jobs refreshed and confirmed completion releases slots");
    std::cout<<"PASS "<<checks<<" File Manager request and receipt checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<checks<<": "<<e.what()<<'\n';return 1;}}
